public class MatrixChainMultiplication {

    // Time: O(n^3), Space: O(n^2)
    public static int mcmTabulation(int[] p) {
        int n = p.length - 1;
        int[][] dp = new int[n + 1][n + 1];
        // Base case: dp[i][i] = 0 for all i (single matrix, already 0)

        for (int len = 2; len <= n; len++) {              // OUTER: range length
            for (int i = 1; i <= n - len + 1; i++) {     // start of range
                int j = i + len - 1;                      // end of range (inclusive)
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {             // try all split points
                    int cost = dp[i][k] + dp[k + 1][j] + p[i - 1] * p[k] * p[j];
                    dp[i][j] = Math.min(dp[i][j], cost);
                }
            }
        }
        return dp[1][n];
    }

    public static void main(String[] args) {
        int[] p = {10, 30, 5, 60, 40};
        System.out.println(mcmTabulation(p));  // Output: 15500
    }
}

