/*
 * MULTI-STATE DP PATTERN
 * When tracking ONE value per position isn't enough.
 * 
 * Key Insight: Some problems need to track MULTIPLE possibilities
 * at each position because a "bad" value now might become "good" later.
 * 
 * Example: Maximum Product Subarray
 * - Negative × Negative = Positive
 * - So current MINIMUM might become future MAXIMUM!
 * - Must track BOTH currMax AND currMin at each position
 */

// MAXIMUM PRODUCT SUBARRAY
// Track both max and min ending at each position
// Time: O(n), Space: O(1)
public int maxProduct(int[] nums) {
    int maxProd = nums[0];
    int currMax = nums[0];  // Max product ending here
    int currMin = nums[0];  // Min product ending here (for negatives!)

    for (int i = 1; i < nums.length; i++) {
        // When we multiply by negative, max and min swap!
        // So we need to consider: just nums[i], or extend previous max/min
        int temp = currMax;
        currMax = Math.max(nums[i], Math.max(nums[i] * currMax, nums[i] * currMin));
        currMin = Math.min(nums[i], Math.min(nums[i] * temp, nums[i] * currMin));

        maxProd = Math.max(maxProd, currMax);
    }
    return maxProd;
}

// BEST TIME TO BUY AND SELL STOCK WITH COOLDOWN
// States: hold (have stock), sold (just sold), rest (cooldown)
// Time: O(n), Space: O(1)
public int maxProfitCooldown(int[] prices) {
    int hold = Integer.MIN_VALUE;  // Max profit while holding stock
    int sold = 0;                   // Max profit just after selling
    int rest = 0;                   // Max profit during cooldown

    for (int price : prices) {
        int prevHold = hold;
        hold = Math.max(hold, rest - price);   // Keep holding OR buy after rest
        rest = Math.max(rest, sold);           // Keep resting OR cooldown after sell
        sold = prevHold + price;               // Sell what we're holding
    }
    return Math.max(sold, rest);
}

// BEST TIME TO BUY AND SELL STOCK WITH TRANSACTION FEE
// States: hold (have stock), cash (no stock)
public int maxProfitWithFee(int[] prices, int fee) {
    int hold = -prices[0];  // Bought first stock
    int cash = 0;           // Haven't bought anything

    for (int i = 1; i < prices.length; i++) {
        hold = Math.max(hold, cash - prices[i]);        // Keep OR buy
        cash = Math.max(cash, hold + prices[i] - fee);  // Keep OR sell (with fee)
    }
    return cash;
}

// PAINT HOUSE - 3 colors, no adjacent same color
// States: cost ending with each color
public int minCostPaintHouse(int[][] costs) {
    int n = costs.length;
    int red = costs[0][0], blue = costs[0][1], green = costs[0][2];

    for (int i = 1; i < n; i++) {
        int newRed = costs[i][0] + Math.min(blue, green);
        int newBlue = costs[i][1] + Math.min(red, green);
        int newGreen = costs[i][2] + Math.min(red, blue);
        red = newRed; blue = newBlue; green = newGreen;
    }
    return Math.min(red, Math.min(blue, green));
}

