function minCostPaintHouse(costs) {
    const n = costs.length;
    let [red, blue, green] = costs[0];

    for (let i = 1; i < n; i++) {
        const newRed = costs[i][0] + Math.min(blue, green);
        const newBlue = costs[i][1] + Math.min(red, green);
