// Climbing Stairs - Memoization
// TIME: O(n), SPACE: O(n)

public int climbStairs(int n) {
    return solve(n, new int[n + 2]);
}

private int solve(int n, int[] memo) {
    if (n <= 1) return 1;
    if (memo[n] != 0) return memo[n];
    memo[n] = solve(n - 1, memo) + solve(n - 2, memo);
    return memo[n];
}

