// 1D DP - Recursion
// Build answer from smaller subproblems
// dp[n] depends on dp[n-1], dp[n-2], etc.
// TIME: O(2^n), SPACE: O(n)

// COUNT WAYS (Climbing Stairs, Decode Ways)
public int countWays(int n) {
    if (n <= 1) return 1;
    return countWays(n - 1) + countWays(n - 2);
}

// MINIMIZE COST (Min Cost Climbing Stairs)
public int minCost(int n, int[] cost) {
    if (n <= 1) return 0;
    return Math.min(
        minCost(n - 1, cost) + cost[n - 1],
        minCost(n - 2, cost) + cost[n - 2]
    );
}

// MAXIMIZE VALUE
public int maxValue(int n, int[] values) {
    if (n <= 0) return 0;
    return Math.max(
        maxValue(n - 1, values),
        maxValue(n - 2, values) + values[n - 1]
    );
}

// FEASIBILITY (can we reach n?)
public boolean canReach(int n, int[] steps) {
    if (n == 0) return true;
    if (n < 0) return false;
    for (int step : steps) {
        if (canReach(n - step, steps)) return true;
    }
    return false;
}

