    if (n <= 1) return 0;
    if (memo[n] != -1) return memo[n];
    memo[n] = Math.min(
        minCost(n - 1, cost, memo) + cost[n - 1],
        minCost(n - 2, cost, memo) + cost[n - 2]
    );
    return memo[n];
}

// MAXIMIZE VALUE
public int maxValue(int n, int[] values, int[] memo) {
    if (n <= 0) return 0;
    if (memo[n] != -1) return memo[n];
    memo[n] = Math.max(
        maxValue(n - 1, values, memo),
        maxValue(n - 2, values, memo) + values[n - 1]
    );
    return memo[n];
}

// FEASIBILITY
// Use int[] memo: -1 = not computed, 0 = false, 1 = true
public boolean canReach(int n, int[] steps, int[] memo) {
    if (n == 0) return true;
    if (n < 0) return false;
    if (memo[n] != -1) return memo[n] == 1;
    for (int step : steps) {
        if (canReach(n - step, steps, memo)) {
            memo[n] = 1;
            return true;
        }
    }
    memo[n] = 0;
    return false;
}

