// 1D DP - Tabulation
// Build from base case up to n
// TIME: O(n), SPACE: O(n)

// COUNT WAYS
public int countWays(int n) {
    if (n <= 1) return 1;
    int[] dp = new int[n + 1];
    dp[0] = 1;
    dp[1] = 1;
    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
}

// MINIMIZE COST
public int minCost(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(
            dp[i - 1] + cost[i - 1],
            dp[i - 2] + cost[i - 2]
        );
    }
    return dp[n];
}

// MAXIMIZE VALUE
public int maxValue(int[] values) {
    int n = values.length;
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Math.max(
            dp[i - 1],
            (i >= 2 ? dp[i - 2] : 0) + values[i - 1]
        );
    }
    return dp[n];
}

// FEASIBILITY
public boolean canReach(int n, int[] steps) {
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
        for (int step : steps) {
            if (i >= step && dp[i - step]) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[n];
}

