// Decision DP - Recursion Template
// At each element: TAKE or SKIP
// TIME: O(2^n), SPACE: O(n)

// MAXIMIZE VALUE (House Robber - can't take adjacent)
public int maxValue(int n, int[] values) {
    if (n < 0) return 0;
    int skip = maxValue(n - 1, values);
    int take = values[n] + maxValue(n - 2, values);
    return Math.max(skip, take);
}

// MINIMIZE COST (Paint House - can't use same adjacent)
public int minCost(int n, int[][] costs, int lastColor) {
    if (n < 0) return 0;
    int result = Integer.MAX_VALUE;
    for (int color = 0; color < costs[0].length; color++) {
        if (color != lastColor) {
            result = Math.min(result,
                costs[n][color] + minCost(n - 1, costs, color));
        }
    }
    return result;
}

// COUNT WAYS (valid arrangements)
public int countWays(int n, boolean canTake) {
    if (n < 0) return 1;
    int skip = countWays(n - 1, true);
    int take = 0;
    if (canTake) take = countWays(n - 1, false);
    return skip + take;
}

// FEASIBILITY (can we reach target?)
public boolean canReach(int n, int[] nums, int target) {
    if (target == 0) return true;
    if (n < 0 || target < 0) return false;
    return canReach(n - 1, nums, target) ||
           canReach(n - 1, nums, target - nums[n]);
}

