// MAXIMIZE VALUE
public int maxValue(int n, int[] values, int[] memo) {
    if (n < 0) return 0;
    if (memo[n] != -1) return memo[n];
    memo[n] = Math.max(
        maxValue(n - 1, values, memo),
        values[n] + maxValue(n - 2, values, memo)
    );
    return memo[n];
}

// MINIMIZE COST
public int minCost(int n, int[][] costs, int lastColor, int[][] memo) {
    if (n < 0) return 0;
    if (lastColor >= 0 && memo[n][lastColor] != -1) return memo[n][lastColor];
    int result = Integer.MAX_VALUE;
    for (int color = 0; color < costs[0].length; color++) {
        if (color != lastColor) {
            result = Math.min(result,
                costs[n][color] + minCost(n - 1, costs, color, memo));
        }
    }
    if (lastColor >= 0) memo[n][lastColor] = result;
    return result;
}

// COUNT WAYS
public int countWays(int n, int canTake, int[][] memo) {
    if (n < 0) return 1;
    if (memo[n][canTake] != -1) return memo[n][canTake];
    int result = countWays(n - 1, 1, memo);
    if (canTake == 1) result += countWays(n - 1, 0, memo);
    memo[n][canTake] = result;
    return result;
}

