// Decision DP - Tabulation Template
// TIME: O(n), SPACE: O(n)

// MAXIMIZE VALUE (House Robber)
public int maxValue(int[] values) {
    int n = values.length;
    if (n == 0) return 0;
    if (n == 1) return values[0];

    int[] dp = new int[n];
    dp[0] = values[0];
    dp[1] = Math.max(values[0], values[1]);

    for (int i = 2; i < n; i++) {
        dp[i] = Math.max(dp[i-1], values[i] + dp[i-2]);
    }
    return dp[n-1];
}

// MINIMIZE COST (Paint House)
public int minCost(int[][] costs) {
    int n = costs.length;
    int k = costs[0].length;
    int[][] dp = new int[n][k];

    for (int c = 0; c < k; c++) dp[0][c] = costs[0][c];

    for (int i = 1; i < n; i++) {
        for (int c = 0; c < k; c++) {
            dp[i][c] = Integer.MAX_VALUE;
            for (int prev = 0; prev < k; prev++) {
                if (prev != c) {
                    dp[i][c] = Math.min(dp[i][c],
                        costs[i][c] + dp[i-1][prev]);
                }
            }
        }
    }
    return Arrays.stream(dp[n-1]).min().getAsInt();
}

// COUNT WAYS
public int countWays(int n) {
    int[][] dp = new int[n + 1][2];
    dp[0][0] = 1; dp[0][1] = 1;
    for (int i = 1; i <= n; i++) {
        dp[i][0] = dp[i-1][1];
        dp[i][1] = dp[i-1][0] + dp[i-1][1];
    }
    return dp[n][0] + dp[n][1];
}

