// Decision DP - Space Optimized Template
// TIME: O(n), SPACE: O(1)

// MAXIMIZE VALUE (House Robber)
public int maxValue(int[] values) {
    int n = values.length;
    if (n == 0) return 0;
    if (n == 1) return values[0];

    int prev2 = values[0];
    int prev1 = Math.max(values[0], values[1]);

    for (int i = 2; i < n; i++) {
        int curr = Math.max(prev1, values[i] + prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

// MINIMIZE COST (Paint House - O(k) space)
public int minCost(int[][] costs) {
    int n = costs.length;
    int k = costs[0].length;
    int[] prev = costs[0].clone();

    for (int i = 1; i < n; i++) {
        int[] curr = new int[k];
        for (int c = 0; c < k; c++) {
            curr[c] = Integer.MAX_VALUE;
            for (int p = 0; p < k; p++) {
                if (p != c) curr[c] = Math.min(curr[c], costs[i][c] + prev[p]);
            }
        }
        prev = curr;
    }
    return Arrays.stream(prev).min().getAsInt();
}

// COUNT WAYS (O(1) space)
public int countWays(int n) {
    int took = 1, skipped = 1;
    for (int i = 1; i <= n; i++) {
        int newTook = skipped;
        int newSkipped = took + skipped;
        took = newTook;
        skipped = newSkipped;
    }
    return took + skipped;
}

