// 0/1 Knapsack - Recursion
// Each item can be used at most once
// TIME: O(2^n), SPACE: O(n)

// MAXIMIZE VALUE (Classic Knapsack)
public int maxValue(int i, int[] weights, int[] values, int capacity) {
    if (i < 0 || capacity == 0) return 0;

    int skip = maxValue(i - 1, weights, values, capacity);

    int take = 0;
    if (weights[i] <= capacity) {
        take = values[i] + maxValue(i - 1, weights, values, capacity - weights[i]);
    }

    return Math.max(skip, take);
}

// COUNT WAYS (Target Sum, Subset Sum count)
public int countWays(int i, int[] nums, int target) {
    if (target == 0) return 1;
    if (i < 0 || target < 0) return 0;

    return countWays(i - 1, nums, target) +
           countWays(i - 1, nums, target - nums[i]);
}

// MINIMIZE COUNT (Min items to fill capacity)
public int minCount(int i, int[] weights, int capacity) {
    if (capacity == 0) return 0;
    if (i < 0) return Integer.MAX_VALUE;

    int skip = minCount(i - 1, weights, capacity);

    int take = Integer.MAX_VALUE;
    if (weights[i] <= capacity) {
        int sub = minCount(i - 1, weights, capacity - weights[i]);
        if (sub != Integer.MAX_VALUE) take = 1 + sub;
    }

    return Math.min(skip, take);
}

// FEASIBILITY (Subset Sum, Partition Equal)
public boolean canMake(int i, int[] nums, int target) {
    if (target == 0) return true;
    if (i < 0 || target < 0) return false;

    return canMake(i - 1, nums, target) ||
           canMake(i - 1, nums, target - nums[i]);
}

