// MAXIMIZE VALUE
public int maxValue(int i, int[] weights, int[] values, int capacity, int[][] memo) {
    if (i < 0 || capacity == 0) return 0;
    if (memo[i][capacity] != -1) return memo[i][capacity];

    int skip = maxValue(i - 1, weights, values, capacity, memo);
    int take = 0;
    if (weights[i] <= capacity) {
        take = values[i] + maxValue(i - 1, weights, values, capacity - weights[i], memo);
    }

    memo[i][capacity] = Math.max(skip, take);
    return memo[i][capacity];
}

// COUNT WAYS
public int countWays(int i, int[] nums, int target, int[][] memo) {
    if (target == 0) return 1;
    if (i < 0 || target < 0) return 0;
    if (memo[i][target] != -1) return memo[i][target];

    memo[i][target] = countWays(i - 1, nums, target, memo) +
                      countWays(i - 1, nums, target - nums[i], memo);
    return memo[i][target];
}

// FEASIBILITY (use int: -1=uncomputed, 0=false, 1=true)
public boolean canMake(int i, int[] nums, int target, int[][] memo) {
    if (target == 0) return true;
    if (i < 0 || target < 0) return false;
    if (memo[i][target] != -1) return memo[i][target] == 1;

    boolean result = canMake(i - 1, nums, target, memo) ||
                     canMake(i - 1, nums, target - nums[i], memo);
    memo[i][target] = result ? 1 : 0;
    return result;
}

