// 0/1 Knapsack - Tabulation (2D)
// TIME: O(n * capacity), SPACE: O(n * capacity)

// MAXIMIZE VALUE
public int maxValue(int[] weights, int[] values, int capacity) {
    int n = weights.length;
    int[][] dp = new int[n + 1][capacity + 1];

    for (int i = 1; i <= n; i++) {
        for (int c = 0; c <= capacity; c++) {
            dp[i][c] = dp[i-1][c];  // skip
            if (weights[i-1] <= c) {
                dp[i][c] = Math.max(dp[i][c],
                    values[i-1] + dp[i-1][c - weights[i-1]]);
            }
        }
    }
    return dp[n][capacity];
}

// COUNT WAYS
public int countWays(int[] nums, int target) {
    int n = nums.length;
    int[][] dp = new int[n + 1][target + 1];
    for (int i = 0; i <= n; i++) dp[i][0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int t = 0; t <= target; t++) {
            dp[i][t] = dp[i-1][t];
            if (nums[i-1] <= t) {
                dp[i][t] += dp[i-1][t - nums[i-1]];
            }
        }
    }
    return dp[n][target];
}

// FEASIBILITY
public boolean canMake(int[] nums, int target) {
    int n = nums.length;
    boolean[][] dp = new boolean[n + 1][target + 1];
    for (int i = 0; i <= n; i++) dp[i][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int t = 0; t <= target; t++) {
            dp[i][t] = dp[i-1][t];
            if (nums[i-1] <= t) {
                dp[i][t] = dp[i][t] || dp[i-1][t - nums[i-1]];
            }
        }
    }
    return dp[n][target];
}

templates.spaceOptimized:
// 0/1 Knapsack - Space Optimized (1D)
// BACKWARD loop prevents item reuse
// TIME: O(n * capacity), SPACE: O(capacity)

// MAXIMIZE VALUE
public int maxValue(int[] weights, int[] values, int capacity) {
    int[] dp = new int[capacity + 1];

    for (int i = 0; i < weights.length; i++) {
        for (int c = capacity; c >= weights[i]; c--) {  // BACKWARD!
            dp[c] = Math.max(dp[c], values[i] + dp[c - weights[i]]);
        }
    }
    return dp[capacity];
}

// COUNT WAYS
public int countWays(int[] nums, int target) {
    int[] dp = new int[target + 1];
    dp[0] = 1;

    for (int num : nums) {
        for (int t = target; t >= num; t--) {  // BACKWARD!
            dp[t] += dp[t - num];
        }
    }
    return dp[target];
}

// FEASIBILITY
public boolean canMake(int[] nums, int target) {
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int t = target; t >= num; t--) {  // BACKWARD!
            dp[t] = dp[t] || dp[t - num];
        }
    }
    return dp[target];
}

// Remember:
// 0/1 Knapsack: BACKWARD (each item once)
// Unbounded:    FORWARD  (unlimited items)

