templates.recursion:
// Unbounded Knapsack - Recursion Template
// Each item can be used unlimited times
// TIME: O(n^capacity), SPACE: O(capacity)

// MAXIMIZE VALUE
public int maxValue(int[] weights, int[] values, int capacity) {
    return solve(weights, values, capacity);
}

private int solve(int[] weights, int[] values, int cap) {
    if (cap == 0) return 0;

    int best = 0;
    for (int i = 0; i < weights.length; i++) {
        if (weights[i] <= cap) {
            best = Math.max(best, values[i] + solve(weights, values, cap - weights[i]));
        }
    }
    return best;
}

// MINIMIZE COUNT (e.g., Coin Change)
public int minCount(int[] items, int target) {
    if (target == 0) return 0;

    int best = Integer.MAX_VALUE;
    for (int item : items) {
        if (item <= target) {
            int sub = minCount(items, target - item);
            if (sub != Integer.MAX_VALUE) {
                best = Math.min(best, 1 + sub);
            }
        }
    }
    return best;
}

// COUNT COMBINATIONS (items outer)
public int countCombinations(int n, int[] items, int target) {
    if (target == 0) return 1;
    if (n < 0 || target < 0) return 0;

    return countCombinations(n - 1, items, target) +
           countCombinations(n, items, target - items[n]);
}

// COUNT PERMUTATIONS (try all items at each capacity)
public int countPermutations(int[] items, int target) {
    if (target == 0) return 1;

    int count = 0;
    for (int item : items) {
        if (item <= target) {
            count += countPermutations(items, target - item);
        }
    }
    return count;
}

templates.memoization:
// Unbounded Knapsack - Memoization Template
// TIME: O(n * capacity), SPACE: O(capacity)

// MAXIMIZE VALUE
public int maxValue(int[] weights, int[] values, int capacity) {
    int[] memo = new int[capacity + 1];
    Arrays.fill(memo, -1);
    return solve(weights, values, capacity, memo);
}

private int solve(int[] weights, int[] values, int cap, int[] memo) {
    if (cap == 0) return 0;
    if (memo[cap] != -1) return memo[cap];

    int best = 0;
    for (int i = 0; i < weights.length; i++) {
        if (weights[i] <= cap) {
            best = Math.max(best, values[i] + solve(weights, values, cap - weights[i], memo));
        }
    }
    memo[cap] = best;
    return best;
}

// MINIMIZE COUNT
public int minCount(int[] items, int target) {
    int[] memo = new int[target + 1];
    Arrays.fill(memo, -1);
    int result = solveMin(items, target, memo);
    return result == Integer.MAX_VALUE ? -1 : result;
}

private int solveMin(int[] items, int target, int[] memo) {
    if (target == 0) return 0;
    if (memo[target] != -1) return memo[target];

    int best = Integer.MAX_VALUE;
    for (int item : items) {
        if (item <= target) {
            int sub = solveMin(items, target - item, memo);
            if (sub != Integer.MAX_VALUE) {
                best = Math.min(best, 1 + sub);
            }
        }
    }
    memo[target] = best;
    return best;
}

// COUNT COMBINATIONS
public int countCombinations(int[] items, int target) {
    int[][] memo = new int[items.length][target + 1];
    for (int[] row : memo) Arrays.fill(row, -1);
    return solveCount(items.length - 1, items, target, memo);
}

private int solveCount(int n, int[] items, int target, int[][] memo) {
    if (target == 0) return 1;
    if (n < 0 || target < 0) return 0;
    if (memo[n][target] != -1) return memo[n][target];

    memo[n][target] = solveCount(n - 1, items, target, memo) +
                      solveCount(n, items, target - items[n], memo);
    return memo[n][target];
}

