// Unbounded Knapsack - Tabulation Template
// FORWARD loop allows item reuse
// TIME: O(n * capacity), SPACE: O(capacity)

// MAXIMIZE VALUE
public int maxValue(int[] weights, int[] values, int capacity) {
    int[] dp = new int[capacity + 1];

    for (int i = 0; i < weights.length; i++) {
        for (int c = weights[i]; c <= capacity; c++) {  // FORWARD!
            dp[c] = Math.max(dp[c], values[i] + dp[c - weights[i]]);
        }
    }
    return dp[capacity];
}

// MINIMIZE COUNT (Coin Change)
public int minCount(int[] items, int target) {
    int[] dp = new int[target + 1];
    Arrays.fill(dp, target + 1);
    dp[0] = 0;

    for (int item : items) {
        for (int t = item; t <= target; t++) {  // FORWARD!
            dp[t] = Math.min(dp[t], 1 + dp[t - item]);
        }
    }
    return dp[target] > target ? -1 : dp[target];
}

// COUNT COMBINATIONS (Coin Change II)
// Items OUTER loop = unordered combinations
public int countCombinations(int[] items, int target) {
    int[] dp = new int[target + 1];
    dp[0] = 1;

    for (int item : items) {              // Items outer
        for (int t = item; t <= target; t++) {
            dp[t] += dp[t - item];
        }
    }
    return dp[target];
}

// COUNT PERMUTATIONS (Combination Sum IV)
// Amounts OUTER loop = ordered permutations
public int countPermutations(int[] items, int target) {
    int[] dp = new int[target + 1];
    dp[0] = 1;

    for (int t = 1; t <= target; t++) {   // Amounts outer
        for (int item : items) {
            if (item <= t) {
                dp[t] += dp[t - item];
            }
        }
    }
    return dp[target];
}

