// LCS Pattern - Recursion
// Compare two sequences from end
// If match: include and move both pointers
// If no match: try excluding each
// TIME: O(2^(m+n)), SPACE: O(m+n)

// MAXIMIZE LENGTH (Longest Common Subsequence)
public int lcsLength(int i, int j, String s1, String s2) {
    if (i < 0 || j < 0) return 0;

    if (s1.charAt(i) == s2.charAt(j)) {
        return 1 + lcsLength(i - 1, j - 1, s1, s2);
    }
    return Math.max(
        lcsLength(i - 1, j, s1, s2),
        lcsLength(i, j - 1, s1, s2)
    );
}

// MINIMIZE OPERATIONS (Edit Distance)
public int minEdit(int i, int j, String s1, String s2) {
    if (i < 0) return j + 1;  // insert remaining
    if (j < 0) return i + 1;  // delete remaining

    if (s1.charAt(i) == s2.charAt(j)) {
        return minEdit(i - 1, j - 1, s1, s2);
    }
    return 1 + Math.min(
        minEdit(i - 1, j, s1, s2),     // delete
        Math.min(
            minEdit(i, j - 1, s1, s2),     // insert
            minEdit(i - 1, j - 1, s1, s2)  // replace
        )
    );
}

// COUNT WAYS (Distinct Subsequences)
public int countWays(int i, int j, String s, String t) {
    if (j < 0) return 1;  // found complete match
    if (i < 0) return 0;  // s exhausted, t not matched

    int ways = countWays(i - 1, j, s, t);  // skip s[i]
    if (s.charAt(i) == t.charAt(j)) {
        ways += countWays(i - 1, j - 1, s, t);  // use s[i]
    }
    return ways;
}

