// MAXIMIZE LENGTH
public int lcsLength(int i, int j, String s1, String s2, int[][] memo) {
    if (i < 0 || j < 0) return 0;
    if (memo[i][j] != -1) return memo[i][j];

    if (s1.charAt(i) == s2.charAt(j)) {
        memo[i][j] = 1 + lcsLength(i - 1, j - 1, s1, s2, memo);
    } else {
        memo[i][j] = Math.max(
            lcsLength(i - 1, j, s1, s2, memo),
            lcsLength(i, j - 1, s1, s2, memo)
        );
    }
    return memo[i][j];
}

// MINIMIZE OPERATIONS (Edit Distance)
public int minEdit(int i, int j, String s1, String s2, int[][] memo) {
    if (i < 0) return j + 1;
    if (j < 0) return i + 1;
    if (memo[i][j] != -1) return memo[i][j];

    if (s1.charAt(i) == s2.charAt(j)) {
        memo[i][j] = minEdit(i - 1, j - 1, s1, s2, memo);
    } else {
        memo[i][j] = 1 + Math.min(
            minEdit(i - 1, j, s1, s2, memo),
            Math.min(
                minEdit(i, j - 1, s1, s2, memo),
                minEdit(i - 1, j - 1, s1, s2, memo)
            )
        );
    }
    return memo[i][j];
}

// COUNT WAYS (Distinct Subsequences)
public int countWays(int i, int j, String s, String t, int[][] memo) {
    if (j < 0) return 1;
    if (i < 0) return 0;
    if (memo[i][j] != -1) return memo[i][j];

    memo[i][j] = countWays(i - 1, j, s, t, memo);
    if (s.charAt(i) == t.charAt(j)) {
        memo[i][j] += countWays(i - 1, j - 1, s, t, memo);
    }
    return memo[i][j];
}

