// LCS Pattern - Space Optimized
// Keep only previous row
// TIME: O(m * n), SPACE: O(min(m, n))

// MAXIMIZE LENGTH
public int lcsLength(String s1, String s2) {
    if (s1.length() < s2.length()) {
        String temp = s1; s1 = s2; s2 = temp;
    }
    int m = s1.length(), n = s2.length();
    int[] prev = new int[n + 1];
    int[] curr = new int[n + 1];

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1.charAt(i-1) == s2.charAt(j-1)) {
                curr[j] = 1 + prev[j-1];
            } else {
                curr[j] = Math.max(prev[j], curr[j-1]);
            }
        }
        int[] temp = prev; prev = curr; curr = temp;
    }
    return prev[n];
}

// MINIMIZE OPERATIONS (Edit Distance)
public int minEdit(String s1, String s2) {
    int m = s1.length(), n = s2.length();
    int[] prev = new int[n + 1];
    for (int j = 0; j <= n; j++) prev[j] = j;
    int[] curr = new int[n + 1];

    for (int i = 1; i <= m; i++) {
        curr[0] = i;
        for (int j = 1; j <= n; j++) {
            if (s1.charAt(i-1) == s2.charAt(j-1)) {
                curr[j] = prev[j-1];
            } else {
                curr[j] = 1 + Math.min(prev[j], Math.min(curr[j-1], prev[j-1]));
            }
        }
        int[] temp = prev; prev = curr; curr = temp;
    }
    return prev[n];
}

// COUNT WAYS (Distinct Subsequences)
public int countWays(String s, String t) {
    int m = s.length(), n = t.length();
    int[] prev = new int[n + 1];
    prev[0] = 1;

    for (int i = 1; i <= m; i++) {
        int[] curr = new int[n + 1];
        curr[0] = 1;
        for (int j = 1; j <= n; j++) {
            curr[j] = prev[j];
            if (s.charAt(i-1) == t.charAt(j-1)) {
                curr[j] += prev[j-1];
            }
        }
        prev = curr;
    }
    return prev[n];
}

