templates.recursion:
// LIS Pattern - Recursion
// At each position: include if satisfies ordering constraint
// Track previous element to check constraint
// TIME: O(2^n), SPACE: O(n)

// MAXIMIZE LENGTH (Longest Increasing Subsequence)
public int lisLength(int index, int prevIndex, int[] nums) {
    if (index == nums.length) return 0;

    int skip = lisLength(index + 1, prevIndex, nums);

    int take = 0;
    if (prevIndex == -1 || nums[index] > nums[prevIndex]) {
        take = 1 + lisLength(index + 1, index, nums);
    }

    return Math.max(skip, take);
}

// MAXIMIZE SUM (Max Sum Increasing Subsequence)
public int lisSum(int index, int prevIndex, int[] nums) {
    if (index == nums.length) return 0;

    int skip = lisSum(index + 1, prevIndex, nums);

    int take = 0;
    if (prevIndex == -1 || nums[index] > nums[prevIndex]) {
        take = nums[index] + lisSum(index + 1, index, nums);
    }

    return Math.max(skip, take);
}

// COUNT WAYS (Number of LIS)
// Returns int[] {length, count}
public int[] countLIS(int index, int prevIndex, int[] nums) {
    if (index == nums.length) return new int[]{0, 1};

    int[] skipResult = countLIS(index + 1, prevIndex, nums);
    int skipLen = skipResult[0], skipCnt = skipResult[1];

    int takeLen = 0, takeCnt = 0;
    if (prevIndex == -1 || nums[index] > nums[prevIndex]) {
        int[] takeResult = countLIS(index + 1, index, nums);
        takeLen = 1 + takeResult[0];
        takeCnt = takeResult[1];
    }

    if (takeLen > skipLen) return new int[]{takeLen, takeCnt};
    if (takeLen < skipLen) return new int[]{skipLen, skipCnt};
    return new int[]{takeLen, takeCnt + skipCnt};
}

