// LIS Pattern - Tabulation
// dp[i] = answer for subsequence ending at index i
// TIME: O(n^2), SPACE: O(n)

// MAXIMIZE LENGTH
public int lisLength(int[] nums) {
    int n = nums.length;
    if (n == 0) return 0;

    int[] dp = new int[n];
    Arrays.fill(dp, 1);
    int maxLen = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        maxLen = Math.max(maxLen, dp[i]);
    }
    return maxLen;
}

// MAXIMIZE SUM
public int lisSum(int[] nums) {
    int n = nums.length;
    if (n == 0) return 0;

    int[] dp = nums.clone();  // dp[i] = max sum ending at i
    int maxSum = nums[0];

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                dp[i] = Math.max(dp[i], dp[j] + nums[i]);
            }
        }
        maxSum = Math.max(maxSum, dp[i]);
    }
    return maxSum;
}

// COUNT WAYS (Number of LIS)
public int countLIS(int[] nums) {
    int n = nums.length;
    if (n == 0) return 0;

    int[] len = new int[n];  // LIS length ending at i
    int[] cnt = new int[n];  // count of LIS ending at i
    Arrays.fill(len, 1);
    Arrays.fill(cnt, 1);

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                if (len[j] + 1 > len[i]) {
                    len[i] = len[j] + 1;
                    cnt[i] = cnt[j];
                } else if (len[j] + 1 == len[i]) {
                    cnt[i] += cnt[j];
                }
            }
        }
    }

    int maxLen = Arrays.stream(len).max().getAsInt();
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (len[i] == maxLen) total += cnt[i];
    }
    return total;
}

