// LIS Pattern - Binary Search O(n log n)
// Maintain smallest tail for each LIS length
// TIME: O(n log n), SPACE: O(n)

// MAXIMIZE LENGTH
public int lisLength(int[] nums) {
    List<Integer> tails = new ArrayList<>();

    for (int num : nums) {
        int left = 0, right = tails.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (tails.get(mid) < num) left = mid + 1;
            else right = mid;
        }

        if (left == tails.size()) tails.add(num);
        else tails.set(left, num);
    }

    return tails.size();
}

// Non-decreasing variant (>= instead of >)
public int longestNonDecreasing(int[] nums) {
    List<Integer> tails = new ArrayList<>();

    for (int num : nums) {
        int left = 0, right = tails.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (tails.get(mid) <= num) left = mid + 1;  // <= for non-decreasing
            else right = mid;
        }

        if (left == tails.size()) tails.add(num);
        else tails.set(left, num);
    }

    return tails.size();
}

// Longest Decreasing Subsequence
public int ldsLength(int[] nums) {
    List<Integer> tails = new ArrayList<>();

    for (int num : nums) {
        int left = 0, right = tails.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (tails.get(mid) > num) left = mid + 1;  // > for decreasing
            else right = mid;
        }

        if (left == tails.size()) tails.add(num);
        else tails.set(left, num);
    }

    return tails.size();
}

