// Interval DP - Recursion
// Solve subproblems on ranges [i, j]
// Try all split points k between i and j
// TIME: O(3^n), SPACE: O(n)

// MINIMIZE COST (Matrix Chain Multiplication)
public int minCost(int i, int j, int[] dims) {
    if (i >= j) return 0;

    int result = Integer.MAX_VALUE;
    for (int k = i; k < j; k++) {
        int cost = minCost(i, k, dims) +
                   minCost(k + 1, j, dims) +
                   dims[i-1] * dims[k] * dims[j];
        result = Math.min(result, cost);
    }
    return result;
}

// MAXIMIZE VALUE (Burst Balloons)
public int maxCoins(int i, int j, int[] arr) {
    if (i > j) return 0;

    int result = 0;
    for (int k = i; k <= j; k++) {
        int coins = arr[i-1] * arr[k] * arr[j+1];
        int left = maxCoins(i, k - 1, arr);
        int right = maxCoins(k + 1, j, arr);
        result = Math.max(result, left + coins + right);
    }
    return result;
}

// FEASIBILITY (Can partition into valid palindromes?)
public boolean canPartition(String s, int i) {
    if (i == s.length()) return true;
    for (int j = i; j < s.length(); j++) {
        if (isPalin(s, i, j) && canPartition(s, j + 1)) {
            return true;
        }
    }
    return false;
}

