// Interval DP - Memoization
// TIME: O(n^3), SPACE: O(n^2)

// MINIMIZE COST
public int minCost(int i, int j, int[] dims, int[][] memo) {
    if (i >= j) return 0;
    if (memo[i][j] != -1) return memo[i][j];

    int result = Integer.MAX_VALUE;
    for (int k = i; k < j; k++) {
        int cost = minCost(i, k, dims, memo) +
                   minCost(k + 1, j, dims, memo) +
                   dims[i-1] * dims[k] * dims[j];
        result = Math.min(result, cost);
    }
    memo[i][j] = result;
    return result;
}

// MAXIMIZE VALUE (Burst Balloons)
public int maxCoins(int i, int j, int[] arr, int[][] memo) {
    if (i > j) return 0;
    if (memo[i][j] != -1) return memo[i][j];

    int result = 0;
    for (int k = i; k <= j; k++) {
        int coins = arr[i-1] * arr[k] * arr[j+1];
        result = Math.max(result,
            maxCoins(i, k - 1, arr, memo) + coins +
            maxCoins(k + 1, j, arr, memo));
    }
    memo[i][j] = result;
    return result;
}

// MINIMIZE CUTS (Palindrome Partitioning II)
public int minCuts(String s, int i, boolean[][] isPalin, int[] memo) {
    if (i == s.length()) return -1;
    if (memo[i] != -1) return memo[i];

    int result = Integer.MAX_VALUE;
    for (int j = i; j < s.length(); j++) {
        if (s.charAt(i) == s.charAt(j) && 
            (j - i < 2 || isPalin[i+1][j-1])) {
            isPalin[i][j] = true;
            int sub = minCuts(s, j + 1, isPalin, memo);
            if (sub != Integer.MAX_VALUE) {
                result = Math.min(result, 1 + sub);
            }
        }
    }
    memo[i] = result;
    return result;
}

