// Interval DP - Tabulation
// Fill by increasing interval length
// TIME: O(n^3), SPACE: O(n^2)

// MINIMIZE COST (Matrix Chain Multiplication)
public int minCost(int[] dims) {
    int n = dims.length - 1;
    int[][] dp = new int[n + 1][n + 1];

    for (int len = 2; len <= n; len++) {
        for (int i = 1; i <= n - len + 1; i++) {
            int j = i + len - 1;
            dp[i][j] = Integer.MAX_VALUE;
            for (int k = i; k < j; k++) {
                dp[i][j] = Math.min(dp[i][j],
                    dp[i][k] + dp[k+1][j] + dims[i-1] * dims[k] * dims[j]);
            }
        }
    }
    return dp[1][n];
}

// MAXIMIZE VALUE (Burst Balloons)
public int maxCoins(int[] nums) {
    int n = nums.length;
    int[] arr = new int[n + 2];
    arr[0] = arr[n + 1] = 1;
    for (int i = 0; i < n; i++) arr[i + 1] = nums[i];
    int[][] dp = new int[n + 2][n + 2];

    for (int len = 1; len <= n; len++) {
        for (int i = 1; i <= n - len + 1; i++) {
            int j = i + len - 1;
            for (int k = i; k <= j; k++) {
                dp[i][j] = Math.max(dp[i][j],
                    dp[i][k-1] + arr[i-1] * arr[k] * arr[j+1] + dp[k+1][j]);
            }
        }
    }
    return dp[1][n];
}

// MINIMIZE CUTS (Palindrome Partitioning II)
public int minCuts(String s) {
    int n = s.length();
    boolean[][] isPalin = new boolean[n][n];

    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n; j++) {
            isPalin[i][j] = s.charAt(i) == s.charAt(j) &&
                           (j - i < 2 || isPalin[i+1][j-1]);
        }
    }

    int[] dp = new int[n + 1];
    for (int i = n - 1; i >= 0; i--) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = i; j < n; j++) {
            if (isPalin[i][j]) {
                dp[i] = Math.min(dp[i], 1 + dp[j + 1]);
            }
        }
    }
    return dp[0] - 1;
}

