// Interval DP - Space Optimization Limited
// Most interval DP needs O(n^2) due to 2D dependencies
// TIME: O(n^3), SPACE: O(n^2)

// Some problems allow O(n) if only diagonal access
// Palindrome partition min cuts with O(n) space:

public int minCuts(String s) {
    int n = s.length();
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) dp[i] = i;  // worst case

    for (int center = 0; center < n; center++) {
        // Odd length palindromes
        for (int l = center, r = center; 
             l >= 0 && r < n && s.charAt(l) == s.charAt(r); 
             l--, r++) {
            dp[r] = (l == 0) ? 0 : Math.min(dp[r], dp[l - 1] + 1);
        }
        // Even length palindromes
        for (int l = center, r = center + 1; 
             l >= 0 && r < n && s.charAt(l) == s.charAt(r); 
             l--, r++) {
            dp[r] = (l == 0) ? 0 : Math.min(dp[r], dp[l - 1] + 1);
        }
    }
    return dp[n - 1];
}

// Note: Most interval DP (MCM, Burst Balloons) cannot be
// optimized below O(n^2) space because dp[i][j] depends on
// dp[i][k] and dp[k+1][j] for all k between i and j.

