// Burst Balloons - Recursion
// TIME: O(2^n), SPACE: O(n)

public int maxCoins(int[] nums) {
    int n = nums.length;
    int[] arr = new int[n + 2];
    arr[0] = arr[n + 1] = 1;
    for (int i = 0; i < n; i++) arr[i + 1] = nums[i];
    return solve(1, n, arr);
}

private int solve(int i, int j, int[] arr) {
    if (i > j) return 0;

    int result = 0;
    for (int k = i; k <= j; k++) {
        int coins = arr[i-1] * arr[k] * arr[j+1];
        int left = solve(i, k - 1, arr);
        int right = solve(k + 1, j, arr);
        result = Math.max(result, left + coins + right);
    }

    return result;
}

