        } else if (state == 1) {
            result = Math.max(
                solve(day + 1, 2) + prices[day],
                solve(day + 1, 1)
            );
        } else {
            result = solve(day + 1, 0);
        }

        memo[day][state] = result;
        return result;
    }
}

