public boolean checkValidString(String s) {
    int low = 0, high = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') { low++; high++; }
        else if (c == ')') { low--; high--; }
        else { low--; high++; }  // '*' can be ')', '(' or empty

        if (high < 0) return false;
        low = Math.max(low, 0);
    }
    return low == 0;
}

