// Hand of Straights / Divide Array in Sets of K Consecutive Numbers
public boolean isNStraightHand(int[] hand, int groupSize) {
    if (hand.length % groupSize != 0) return false;

    // Count frequency of each card
    TreeMap<Integer, Integer> count = new TreeMap<>();
    for (int card : hand) {
        count.put(card, count.getOrDefault(card, 0) + 1);
    }

    // Process from smallest card
    while (!count.isEmpty()) {
        int first = count.firstKey();  // smallest card

        // Try to form a group starting from 'first'
        for (int i = 0; i < groupSize; i++) {
            int card = first + i;
            if (!count.containsKey(card)) return false;

            // Decrement count
            int freq = count.get(card);
            if (freq == 1) {
                count.remove(card);
            } else {
                count.put(card, freq - 1);
            }
        }
    }
    return true;
}

