public int canCompleteCircuit(int[] gas, int[] cost) {
    int totalGas = 0;
    int totalCost = 0;
    int tank = 0;
    int start = 0;

    for (int i = 0; i < gas.length; i++) {
        totalGas += gas[i];
        totalCost += cost[i];
        tank += gas[i] - cost[i];

        // Can't reach next station, try starting from i+1
        if (tank < 0) {
            start = i + 1;
            tank = 0;
        }
    }

    // If we have enough total gas, 'start' is the answer
    return totalGas >= totalCost ? start : -1;
}

