function isNStraightHand(hand, groupSize) {
    // Quick check: must be divisible
    if (hand.length % groupSize !== 0) return false;

    // Count frequency of each card
    const count = new Map();
    for (const card of hand) {
        count.set(card, (count.get(card) || 0) + 1);
    }

    // Sort unique cards to process from smallest
    const sortedCards = [...count.keys()].sort((a, b) => a - b);

    // Process from smallest card
    for (const first of sortedCards) {
        const freq = count.get(first);
        if (freq === 0) continue;  // Already used up

        // Form 'freq' groups starting from 'first'
        for (let i = 0; i < groupSize; i++) {
            const card = first + i;
            const cardFreq = count.get(card) || 0;

            // Not enough of this card
            if (cardFreq < freq) return false;

            count.set(card, cardFreq - freq);
        }
    }

    return true;
}

