function reconstructQueue(people) {
    // Sort: tallest first, then by k ascending for same height
    people.sort((a, b) => {
        if (a[0] !== b[0]) return b[0] - a[0];  // Height DESC
        return a[1] - b[1];                      // k ASC (for same height)
    });

