int start = 0, end = 0;

for (int i = 0; i < s.length(); i++) {
    end = Math.max(end, lastIndex[s.charAt(i) - 'a']);

    if (i == end) {
        result.add(end - start + 1);
        start = i + 1;
    }
}
return result;
```

