/*
 * Graph Representation
 * 
 * Adjacency List: O(V + E) space - PREFERRED
 * Adjacency Matrix: O(V²) space
 */

// ===== ADJACENCY LIST (Unweighted) =====
List<List<Integer>> buildAdjList(int n, int[][] edges) {
    List<List<Integer>> adj = new ArrayList<>();

    for (int i = 0; i <= n; i++) {
        adj.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];

        adj.get(u).add(v);
        adj.get(v).add(u);  // Remove for directed graph
    }

    return adj;
}

// ===== ADJACENCY LIST (Weighted) =====
// Each entry: [neighbor, weight]
List<List<int[]>> buildWeightedAdjList(int n, int[][] edges) {
    List<List<int[]>> adj = new ArrayList<>();

    for (int i = 0; i <= n; i++) {
        adj.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int weight = edge[2];

        adj.get(u).add(new int[]{v, weight});
        adj.get(v).add(new int[]{u, weight});  // Remove for directed
    }

    return adj;
}

// ===== ADJACENCY MATRIX =====
int[][] buildAdjMatrix(int n, int[][] edges) {
    int[][] matrix = new int[n + 1][n + 1];

    for (int[] edge : edges) {
        matrix[edge[0]][edge[1]] = 1;
        matrix[edge[1]][edge[0]] = 1;  // Remove for directed
    }

    return matrix;
}

