        int node = queue.poll();
        // Process node here
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;  // Mark BEFORE adding
                queue.offer(neighbor);
            }
        }
    }
}

