/*
 * Find if Path Exists in Graph (LC 1971)
 *
 * Given n nodes labeled 0 to n-1, and edges connecting them,
 * determine if there's a valid path from source to destination.
 *
 * This is the simplest BFS problem - just check reachability.
 *
 * Time: O(V + E)
 * Space: O(V)
 */

class Solution {
    public boolean validPath(int n, int[][] edges, int source, int destination) {
        // Edge case: source equals destination
        if (source == destination) return true;

        // Build adjacency list
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);  // Undirected
        }

        // BFS
        Queue<Integer> queue = new LinkedList<>();
        boolean[] visited = new boolean[n];

        queue.offer(source);
        visited[source] = true;

        while (!queue.isEmpty()) {
            int node = queue.poll();

            for (int neighbor : graph.get(node)) {
                if (neighbor == destination) {
                    return true;  // Found path!
                }
                if (!visited[neighbor]) {
                    visited[neighbor] = true;  // Mark BEFORE adding
                    queue.offer(neighbor);
                }
            }
        }

        return false;  // No path exists
    }
}

