/*
 * Walls and Gates (LC 286)
 *
 * Given a grid where:
 * -1 = wall
 *  0 = gate
 * INF = empty room (use Integer.MAX_VALUE)
 *
 * Fill each empty room with distance to its nearest gate.
 *
 * Multi-source BFS: Start from ALL gates simultaneously.
 * Each cell gets filled with shortest distance to ANY gate.
 *
 * Time: O(m * n)
 * Space: O(m * n)
 */

class Solution {

    private static final int[][] DIRS = {{0,1}, {0,-1}, {1,0}, {-1,0}};
    private static final int INF = Integer.MAX_VALUE;

    public void wallsAndGates(int[][] rooms) {
        if (rooms == null || rooms.length == 0) return;

        int m = rooms.length;
        int n = rooms[0].length;

        Queue<int[]> queue = new LinkedList<>();

        // Step 1: Add ALL gates to queue (multi-source)
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (rooms[i][j] == 0) {  // Gate
                    queue.offer(new int[]{i, j});
                }
            }
        }

        // Step 2: BFS from all gates simultaneously
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int row = curr[0], col = curr[1];

            for (int[] dir : DIRS) {
                int newRow = row + dir[0];
                int newCol = col + dir[1];

                // Boundary check
                if (newRow < 0 || newRow >= m || 
                    newCol < 0 || newCol >= n) {
                    continue;
                }

                // Only process empty rooms (INF)
                // Already processed rooms have smaller values
                if (rooms[newRow][newCol] != INF) {
                    continue;
                }

                // Update distance: current cell distance + 1
                rooms[newRow][newCol] = rooms[row][col] + 1;
                queue.offer(new int[]{newRow, newCol});
            }
        }
    }
}

