/*
 * Shortest Path in Unweighted Graph
 *
 * BFS guarantees shortest path because it explores
 * level by level - all nodes at distance k are
 * processed before any node at distance k+1.
 *
 * Time: O(V + E)
 * Space: O(V)
 */

class Solution {

    // Method 1: Track distance with each node in queue
    public int shortestPath(List<List<Integer>> graph, int source, int dest) {
        if (source == dest) return 0;

        int n = graph.size();
        boolean[] visited = new boolean[n];

        // Queue stores: [node, distance]
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{source, 0});
        visited[source] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int node = curr[0];
            int dist = curr[1];

            for (int neighbor : graph.get(node)) {
                if (neighbor == dest) {
                    return dist + 1;  // Found shortest path!
                }
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.offer(new int[]{neighbor, dist + 1});
                }
            }
        }

        return -1;  // No path exists
    }

    // Method 2: Level-by-level processing
    public int shortestPathLevelByLevel(List<List<Integer>> graph, int source, int dest) {
        if (source == dest) return 0;

        int n = graph.size();
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();

        queue.offer(source);
        visited[source] = true;
        int distance = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();  // Nodes at current level
            distance++;

            // Process all nodes at current distance
            for (int i = 0; i < size; i++) {
                int node = queue.poll();

                for (int neighbor : graph.get(node)) {
                    if (neighbor == dest) {
                        return distance;
                    }
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        queue.offer(neighbor);
                    }
                }
            }
        }

        return -1;
    }
}

