/*
 * Number of Islands - DFS Solution
 *
 * Treat each '1' cell as land. Connected '1's form an island.
 * DFS marks all connected land cells as visited.
 *
 * Time: O(m * n)
 * Space: O(m * n) - visited array + recursion stack
 */
class Solution {
    private static final int[][] DIRS = {{0,1}, {1,0}, {-1,0}, {0,-1}};

    public int numIslands(char[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && grid[i][j] == '1') {
                    count++;
                    dfs(i, j, grid, visited);
                }
            }
        }
        return count;
    }

    private void dfs(int i, int j, char[][] grid, boolean[][] visited) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length) return;
        if (visited[i][j] || grid[i][j] == '0') return;

        visited[i][j] = true;
        for (int[] dir : DIRS) {
            dfs(i + dir[0], j + dir[1], grid, visited);
        }
    }
}

/*
 * Number of Islands - BFS Solution
 *
 * Same idea, but uses queue instead of recursion.
 * Better for very large grids (avoids stack overflow).
 *
 * Time: O(m * n)
 * Space: O(m * n) - visited array + queue
 */
class SolutionBFS {
    private static final int[][] DIRS = {{0,1}, {1,0}, {-1,0}, {0,-1}};

    public int numIslands(char[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && grid[i][j] == '1') {
                    count++;
                    bfs(i, j, grid, visited);
                }
            }
        }
        return count;
    }

    private void bfs(int startR, int startC, char[][] grid, boolean[][] visited) {
        int m = grid.length, n = grid[0].length;
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0], c = cell[1];

            for (int[] dir : DIRS) {
                int nr = r + dir[0], nc = c + dir[1];

                if (nr >= 0 && nr < m && nc >= 0 && nc < n 
                    && !visited[nr][nc] && grid[nr][nc] == '1') {
                    visited[nr][nc] = true;  // Mark BEFORE adding
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }
}

