/*
 * Rotting Oranges - Multi-Source BFS
 *
 * Intuition:
 * ----------
 * Every rotten orange (cell with value 2) is a starting point.
 * From each rotten orange, we spread out in all 4 directions.
 * The first time we reach a fresh orange, that distance is
 * guaranteed to be the shortest time to rot it.
 *
 * This is a classic multi-source BFS problem.
 *
 * Approach:
 * ---------
 * 1. Push all rotten oranges (value = 2) into the queue.
 *    These act as multiple BFS starting points.
 *
 * 2. Run BFS:
 *    - Pop a cell from the queue.
 *    - Try moving in 4 directions.
 *    - If neighboring cell is fresh (1), mark it rotten
 *      and push it into the queue.
 *
 * 3. Because BFS expands level by level, each level
 *    represents one minute passing.
 *
 * Time: O(m * n)
 * Space: O(m * n) for the queue
 */

class Solution {

    private static final int[][] directions = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public int orangesRotting(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return -1;

        int rows = grid.length;
        int cols = grid[0].length;

        Queue<int[]> queue = new LinkedList<>();

        int minutes = 0;
        int freshOranges = 0;

        // Step 1: Add ALL rotten oranges to queue
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 2) {
                    queue.offer(new int[]{i, j});
                } else if (grid[i][j] == 1) {
                    freshOranges++;
                }
            }
        }

        // Step 2: Multi-source BFS
        while (!queue.isEmpty() && freshOranges > 0) {
            int size = queue.size();
            minutes++;

            for (int i = 0; i < size; i++) {
                int[] node = queue.poll();

                for (int[] dir : directions) {
                    int newX = node[0] + dir[0];
                    int newY = node[1] + dir[1];

                    if (newX >= 0 && newX < rows &&
                        newY >= 0 && newY < cols &&
                        grid[newX][newY] == 1) {

                        grid[newX][newY] = 2;
                        freshOranges--;
                        queue.offer(new int[]{newX, newY});
                    }
                }
            }
        }

        return freshOranges > 0 ? -1 : minutes;
    }
}

