/*
 * Clone Graph
 *
 * Intuition:
 * ----------
 * A graph can contain cycles.
 *
 * Example:
 *
 *      1 ---- 2
 *      |      |
 *      |      |
 *      4 ---- 3
 *
 * If we recursively clone neighbors without remembering what we've
 * already cloned, we'll keep visiting the same nodes forever:
 *
 * 1 -> 2 -> 3 -> 4 -> 1 -> ...
 *
 * To avoid this, we use a HashMap:
 *
 *      Original Node -> Cloned Node
 *
 * The map helps us:
 * 1. Avoid infinite recursion caused by cycles.
 * 2. Ensure each node is cloned exactly once.
 * 3. Reuse already-created cloned nodes when encountered again.
 *
 * Time: O(V + E)
 * Space: O(V) for the HashMap
 */

class Solution {

    public Node cloneGraph(Node node) {
        if (node == null) {
            return null;
        }

        // Stores: Original Node -> Cloned Node
        Map<Node, Node> map = new HashMap<>();

        return dfs(node, map);
    }

    private Node dfs(Node node, Map<Node, Node> map) {
        // If already cloned, return the clone
        if (map.containsKey(node)) {
            return map.get(node);
        }

        // Create a clone of current node
        Node copy = new Node(node.val);

        // IMPORTANT: Store clone BEFORE processing neighbors
        // This handles cycles - if we revisit this node,
        // we return the existing clone
        map.put(node, copy);

        // Clone all neighbors recursively
        for (Node nei : node.neighbors) {
            copy.neighbors.add(dfs(nei, map));
        }

        return copy;
    }
}

