/*
 * Clone Graph
 *
 * Use HashMap to track: Original Node -> Cloned Node
 * This prevents infinite loops in cyclic graphs.
 *
 * Time: O(V + E)
 * Space: O(V)
 */

function cloneGraph(node) {
    if (!node) return null;

    const map = new Map();  // Original -> Clone

    const dfs = (n) => {
        // If already cloned, return the clone
        if (map.has(n)) {
            return map.get(n);
        }

        // Create clone
        const copy = { val: n.val, neighbors: [] };

        // Store BEFORE recursing (handles cycles)
        map.set(n, copy);

        // Clone all neighbors
        for (const neighbor of n.neighbors) {
            copy.neighbors.push(dfs(neighbor));
        }

        return copy;
    };

    return dfs(node);
}

