        color[node] = 1;  // Gray

        for (const neighbor of graph[node]) {
            if (color[neighbor] === 1) return true;  // Cycle!
            if (color[neighbor] === 0 && dfs(neighbor)) return true;
        }

        color[node] = 2;  // Black
        return false;
    }

    for (let i = 0; i < n; i++) {
        if (color[i] === 0 && dfs(i)) return true;
    }
    return false;
}

