import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;

class MinHeap {
    private List<Integer> heap = new ArrayList<>();

    // Insert value and restore heap property
    public void insert(int value) {
        heap.add(value);
        bubbleUp(heap.size() - 1);
    }

    // Remove and return minimum (root)
    public int extractMin() {
        if (heap.isEmpty()) throw new NoSuchElementException("Heap is empty");

        int result = heap.get(0);  // Save root
        int last = heap.remove(heap.size() - 1);  // Remove last

        if (!heap.isEmpty()) {
            heap.set(0, last);  // Move last to root
            bubbleDown(0);
        }

        return result;
    }

    // Move element down until heap property is satisfied
    private void bubbleDown(int index) {
        int size = heap.size();

        while (true) {
            int leftChild = 2 * index + 1;
            int rightChild = 2 * index + 2;
            int smallest = index;

            // Find smallest among parent and children
            if (leftChild < size && heap.get(leftChild) < heap.get(smallest)) {
                smallest = leftChild;
            }
            if (rightChild < size && heap.get(rightChild) < heap.get(smallest)) {
                smallest = rightChild;
            }

            // If parent is smallest, heap property restored
            if (smallest == index) break;

            // Swap with smaller child
            swap(index, smallest);
            index = smallest;
        }
    }

    private void bubbleUp(int index) {
        while (index > 0) {
            int parentIdx = (index - 1) / 2;
            if (heap.get(index) >= heap.get(parentIdx)) break;
            swap(index, parentIdx);
            index = parentIdx;
        }
    }

    private void swap(int i, int j) {
        int temp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, temp);
    }

    public int peek() { return heap.get(0); }
    public int size() { return heap.size(); }
    public boolean isEmpty() { return heap.isEmpty(); }
}

