import java.util.Arrays;
import java.util.PriorityQueue;

class MinHeapBuilder {

    // Build min-heap from array in-place - O(n)
    public static void heapify(int[] arr) {
        int n = arr.length;

        // Start from last non-leaf, go backwards to root
        // Leaves (indices n/2 to n-1) are already valid heaps
        for (int i = n / 2 - 1; i >= 0; i--) {
            bubbleDown(arr, n, i);
        }
    }

    // Move element down until heap property is satisfied
    private static void bubbleDown(int[] arr, int n, int i) {
        while (true) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;

            // Find smallest among parent and children
            if (left < n && arr[left] < arr[smallest]) {
                smallest = left;
            }
            if (right < n && arr[right] < arr[smallest]) {
                smallest = right;
            }

            // If parent is smallest, heap property restored
            if (smallest == i) break;

            // Swap with smaller child
            int temp = arr[i];
            arr[i] = arr[smallest];
            arr[smallest] = temp;
            i = smallest;
        }
    }

    public static void main(String[] args) {
        // Example: heapify an unsorted array
        int[] arr = {4, 10, 3, 5, 1};
        System.out.println("Before: " + Arrays.toString(arr));

        heapify(arr);
        System.out.println("After:  " + Arrays.toString(arr));
        // Output: [1, 4, 3, 5, 10] - valid min-heap!

