class MinHeapBuilder {

    // Build min-heap from array in-place - O(n)
    static heapify(arr) {
        const n = arr.length;

        // Start from last non-leaf, go backwards to root
        // Leaves (indices n/2 to n-1) are already valid heaps
        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
            MinHeapBuilder.bubbleDown(arr, n, i);
        }
    }

    // Move element down until heap property is satisfied
    static bubbleDown(arr, n, i) {
        while (true) {
            const left = 2 * i + 1;
            const right = 2 * i + 2;
            let smallest = i;

            // Find smallest among parent and children
            if (left < n && arr[left] < arr[smallest]) {
                smallest = left;
            }
            if (right < n && arr[right] < arr[smallest]) {
                smallest = right;
            }

            // If parent is smallest, heap property restored
            if (smallest === i) break;

            // Swap with smaller child
            [arr[i], arr[smallest]] = [arr[smallest], arr[i]];
            i = smallest;
        }
    }
}

// Example: heapify an unsorted array
const arr = [4, 10, 3, 5, 1];
console.log("Before:", arr);

MinHeapBuilder.heapify(arr);
console.log("After: ", arr);
// Output: [1, 4, 3, 5, 10] - valid min-heap!

// Verify: root (1) is smaller than children (4, 3)
// Node 4 is smaller than children (5, 10)

