import java.util.PriorityQueue;
import java.util.Collections;
import java.util.Arrays;

public class TopKElements {

    // Kth Largest Element - Min-heap approach
    // Time: O(n log k), Space: O(k)
    public static int findKthLargest(int[] nums, int k) {
        // Min-heap of size K
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();

        for (int num : nums) {
            minHeap.offer(num);

            // Keep only K largest
            if (minHeap.size() > k) {
                minHeap.poll();  // Remove smallest (not in top K)
            }
        }

        // Root is Kth largest
        return minHeap.peek();
    }

    // K Smallest Elements - Max-heap approach
    public static int[] kSmallest(int[] nums, int k) {
        // Max-heap of size K
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(
            Collections.reverseOrder()
        );

        for (int num : nums) {
            maxHeap.offer(num);
            if (maxHeap.size() > k) {
                maxHeap.poll();  // Remove largest (not in bottom K)
            }
        }

        // Convert heap to array
        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = maxHeap.poll();
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {3, 2, 1, 5, 6, 4};

        // Find 2nd largest
        System.out.println("2nd largest: " + findKthLargest(nums, 2));  // 5

        // Find 3 smallest elements
        System.out.println("3 smallest: " + Arrays.toString(kSmallest(nums, 3)));  // [3, 2, 1]
    }
}

