import java.util.PriorityQueue;
import java.util.Collections;

class MedianFinder {
    // Max-heap for smaller half (root = largest of small)
    private PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder());
    // Min-heap for larger half (root = smallest of large)
    private PriorityQueue<Integer> large = new PriorityQueue<>();

    public void addNum(int num) {
        // Step 1: Add to max-heap
        small.offer(num);

        // Step 2: Move largest of small to large (ensures partition)
        large.offer(small.poll());

        // Step 3: Rebalance if large has more elements
        if (large.size() > small.size()) {
            small.offer(large.poll());
        }
    }

    public double findMedian() {
        if (small.size() > large.size()) {
            // Odd total: median is in small
            return small.peek();
        }
        // Even total: average of two middle elements
        return (small.peek() + large.peek()) / 2.0;
    }

    public static void main(String[] args) {
        MedianFinder mf = new MedianFinder();

        mf.addNum(5);
        System.out.println("After 5: " + mf.findMedian());    // 5.0

        mf.addNum(2);
        System.out.println("After 2: " + mf.findMedian());    // 3.5

        mf.addNum(8);
        System.out.println("After 8: " + mf.findMedian());    // 5.0

        mf.addNum(1);
        System.out.println("After 1: " + mf.findMedian());    // 3.5
    }
}

