class MedianFinder {
    constructor() {
        this.small = [];  // Max-heap (store negated for max behavior)
        this.large = [];  // Min-heap
    }

    addNum(num) {
        // Step 1: Add to max-heap (negate for max behavior)
        this.small.push(-num);
        this.small.sort((a, b) => a - b);

        // Step 2: Move largest of small to large
        this.large.push(-this.small.shift());
        this.large.sort((a, b) => a - b);

        // Step 3: Rebalance if needed
        if (this.large.length > this.small.length) {
            this.small.push(-this.large.shift());
            this.small.sort((a, b) => a - b);
        }
    }

    findMedian() {
        if (this.small.length > this.large.length) {
            return -this.small[0];  // Odd: middle is in small
        }
        return (-this.small[0] + this.large[0]) / 2;  // Even: average
    }
}

