import java.util.PriorityQueue;
import java.util.Arrays;

// Definition for singly-linked list
class ListNode {
    int val;
    ListNode next;
    ListNode(int val) { this.val = val; }
}

public class MergeKSortedLists {

    // Merge K Sorted Linked Lists
    // Time: O(N log K), Space: O(K)
    public static ListNode mergeKLists(ListNode[] lists) {
        // Min-heap ordered by node value
        PriorityQueue<ListNode> heap = new PriorityQueue<>(
            (a, b) -> a.val - b.val
        );

        // Add first node from each list
        for (ListNode node : lists) {
            if (node != null) {
                heap.offer(node);
            }
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (!heap.isEmpty()) {
            // Get smallest among K candidates
            ListNode node = heap.poll();
            tail.next = node;
            tail = tail.next;

            // Add next element from same list
            if (node.next != null) {
                heap.offer(node.next);
            }
        }

        return dummy.next;
    }

    // Merge K Sorted Arrays
    public static int[] mergeKArrays(int[][] arrays) {
        // heap stores: [value, arrayIndex, elementIndex]
        PriorityQueue<int[]> heap = new PriorityQueue<>(
            (a, b) -> a[0] - b[0]
        );

        int totalSize = 0;
        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i].length > 0) {
                heap.offer(new int[]{arrays[i][0], i, 0});
                totalSize += arrays[i].length;
            }
        }

        int[] result = new int[totalSize];
        int idx = 0;

        while (!heap.isEmpty()) {
            int[] curr = heap.poll();
            result[idx++] = curr[0];

            int arrIdx = curr[1];
            int elemIdx = curr[2];

            if (elemIdx + 1 < arrays[arrIdx].length) {
                heap.offer(new int[]{arrays[arrIdx][elemIdx + 1], arrIdx, elemIdx + 1});
            }
        }

        return result;
    }

    public static void main(String[] args) {
        // Test merge K sorted arrays
        int[][] arrays = {{1, 4, 7}, {2, 5, 8}, {3, 6, 9}};
        int[] merged = mergeKArrays(arrays);
        System.out.println("Merged: " + Arrays.toString(merged));
        // Output: [1, 2, 3, 4, 5, 6, 7, 8, 9]
    }
}

