    let tail = dummy;

    while (heap.length > 0) {
        // Sort to get minimum
        heap.sort((a, b) => a.val - b.val);

        // Get smallest
        const node = heap.shift();
        tail.next = node;
        tail = tail.next;

        // Add next from same list
        if (node.next) heap.push(node.next);
    }

    return dummy.next;
}

