import java.util.*;

class Solution {

    public int leastInterval(char[] tasks, int n) {

        // Frequency of every task A-Z
        int[] freq = new int[26];
        for (char ch : tasks) {
            freq[ch - 'A']++;
        }

        // Max Heap stores remaining frequencies
        // poll() always gives the largest frequency first
        PriorityQueue<Integer> heap =
                new PriorityQueue<>(Collections.reverseOrder());

        for (int f : freq) {
            if (f > 0)
                heap.offer(f);
        }

        int time = 0;

        // Keep scheduling until every task finishes
        while (!heap.isEmpty()) {

            // Stores tasks that still have occurrences left
            // We can't put them back immediately (cooldown)
            List<Integer> temp = new ArrayList<>();

            // One CPU block contains (n + 1) slots
            // Inside these slots, every task must be different
            int cycle = n + 1;

            // Fill this block
            // Stop if block is full OR no tasks remain
            while (cycle > 0 && !heap.isEmpty()) {

                // Most frequent remaining task
                int count = heap.poll();

                // Execute this task once
                // If it still has remaining occurrences, save it
                if (count > 1) {
                    temp.add(count - 1);
                }

                // One CPU interval has passed
                time++;

                // One slot of this block is now used
                cycle--;
            }

            // Cooldown window has ended
            // Tasks with remaining frequency become available again
            heap.addAll(temp);

            // If heap is NOT empty, we must stay idle for remaining slots
            // If heap IS empty, we're done (no need to add idle)
            if (!heap.isEmpty()) {
                time += cycle;
            }
        }

        return time;
    }
}

