class Solution {

    public int leastInterval(char[] tasks, int n) {

        // Count frequency of each task
        int[] freq = new int[26];
        for (char ch : tasks) {
            freq[ch - 'A']++;
        }

        // Find max frequency and how many tasks share it
        int maxFreq = 0;
        int maxCount = 0;
        for (int f : freq) {
            if (f > maxFreq) {
                maxFreq = f;
                maxCount = 1;
            } else if (f == maxFreq) {
                maxCount++;
            }
        }

        // Formula: (maxFreq - 1) full rows of (n+1) slots
        //          + last row of maxCount slots
        int formulaResult = (maxFreq - 1) * (n + 1) + maxCount;

        // If many different tasks fill all gaps, no idle needed
        // Answer is simply total number of tasks
        return Math.max(tasks.length, formulaResult);
    }
}

