import java.util.PriorityQueue;
import java.util.Arrays;

public class KClosestPoints {

    /**
     * K Closest Points to Origin
     * 
     * Approach: MAX-heap of size K
     * - We want K smallest distances, so use MAX-heap
     * - Root = furthest of the K closest (the one to potentially kick out)
     * - Compare squared distances (no need for sqrt)
     * 
     * Time: O(n log k), Space: O(k)
     */
    public static int[][] kClosest(int[][] points, int k) {
        // Max-heap by squared distance (to keep K smallest)
        // Comparator: b - a means larger distances come first (max-heap)
        PriorityQueue<int[]> heap = new PriorityQueue<>(
            (a, b) -> squaredDist(b) - squaredDist(a)
        );

        for (int[] point : points) {
            heap.offer(point);

            // If heap exceeds size k, remove the furthest point
            if (heap.size() > k) {
                heap.poll();  // Removes root (furthest of K closest)
            }
        }

        // Extract all K points from heap
        int[][] result = new int[k][2];
        for (int i = 0; i < k; i++) {
            result[i] = heap.poll();
        }
        return result;
    }

    /**
     * Squared Euclidean distance from origin.
     * No need for sqrt when comparing distances!
     * If sqrt(a) < sqrt(b), then a < b.
     */
    private static int squaredDist(int[] point) {
        return point[0] * point[0] + point[1] * point[1];
    }

    public static void main(String[] args) {
        int[][] points = {{3, 3}, {5, -1}, {-2, 4}};
        int k = 2;

        System.out.println("Points: " + Arrays.deepToString(points));
        System.out.println("Finding " + k + " closest to origin...\n");

        // Show distances for clarity
        for (int[] p : points) {
            int dist = squaredDist(p);
            System.out.printf("  %s -> squared distance = %d%n", 
                Arrays.toString(p), dist);
        }
        System.out.println();

        int[][] result = kClosest(points, k);
        System.out.println("K closest points:");
        for (int[] p : result) {
            System.out.println("  " + Arrays.toString(p));
        }
        // Output: [3, 3] and [-2, 4] (distances 18 and 20)
    }
}

