 * - Root = furthest of the K closest (the one to potentially kick out)
 * - Compare squared distances (no need for sqrt)
 * 
 * Time: O(n log k) with real heap, O(n * k log k) with sorted array
 * Space: O(k)
 */
function kClosest(points, k) {
    // Squared distance from origin (skip sqrt for efficiency)
    const squaredDist = (p) => p[0] * p[0] + p[1] * p[1];

    // Max-heap by distance (simulated with sorted array)
    // In interviews, acknowledge: "I'd use a proper heap library in production"
    const heap = [];

    for (const point of points) {
        heap.push(point);

        // Maintain max-heap order: furthest first
        heap.sort((a, b) => squaredDist(b) - squaredDist(a));

        // If heap exceeds size k, remove the furthest
        if (heap.length > k) {
            heap.shift();  // Remove root (furthest)
        }
    }

    return heap;
}

