    const dist = p[0] * p[0] + p[1] * p[1];
    console.log(`  [${p}] -> squared distance = ${dist}`);
}
console.log();

const result = kClosest(points, k);
console.log("K closest points:", result);
// Output: [[3, 3], [-2, 4]] (distances 18 and 20)

