import java.util.Arrays;
import java.util.PriorityQueue;

public class MeetingRoomsII {

    public static int minMeetingRooms(int[][] intervals) {
        if (intervals.length == 0) return 0;

        // Sort by start time
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);

        // Min-heap of end times (tracks when rooms become free)
        PriorityQueue<Integer> endTimes = new PriorityQueue<>();
        endTimes.offer(intervals[0][1]);

        for (int i = 1; i < intervals.length; i++) {
            // Can reuse room if new meeting starts at or after earliest end
            if (intervals[i][0] >= endTimes.peek()) {
                endTimes.poll();  // Free the room
            }
            // Add this meeting's end time (assign a room)
            endTimes.offer(intervals[i][1]);
        }

        // Heap size = peak concurrent meetings = rooms needed
        return endTimes.size();
    }

    public static void main(String[] args) {
        int[][] intervals = {{0,30},{5,10},{15,20},{20,35},{25,40},{35,50}};
        System.out.println(minMeetingRooms(intervals));  // 3
        // Step 1: [0,30]  -> heap=[30],        rooms=1
        // Step 2: [5,10]  -> heap=[10,30],      rooms=2
        // Step 3: [15,20] -> reuse, heap=[20,30],  rooms=2
        // Step 4: [20,35] -> reuse, heap=[30,35],  rooms=2
        // Step 5: [25,40] -> heap=[30,35,40],   rooms=3  (peak)
        // Step 6: [35,50] -> reuse, heap=[35,40,50], rooms=3
    }
}

