import java.util.PriorityQueue;

public class ReorganizeString {

    public static String reorganizeString(String s) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) freq[c - 'a']++;

        // If any char appears more than ceil(n/2) times, impossible
        int maxFreq = 0;
        for (int f : freq) maxFreq = Math.max(maxFreq, f);
        if (maxFreq > (s.length() + 1) / 2) return "";

        // Max-heap ordered by frequency: [freq, charIndex]
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) heap.offer(new int[]{freq[i], i});
        }

        StringBuilder sb = new StringBuilder();
        int[] prev = null;

        while (!heap.isEmpty()) {
            // Place the most frequent remaining char
            int[] curr = heap.poll();
            sb.append((char)(curr[1] + 'a'));
            curr[0]--;

            // Push previous char back — it is now safe to use again
            if (prev != null && prev[0] > 0) {
                heap.offer(prev);
            }
            prev = curr;  // Hold: cannot place this char next step
        }

        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(reorganizeString("aaabbc"));  // "ababac" (one valid answer)
        System.out.println(reorganizeString("aaab"));    // "" (impossible)
        System.out.println(reorganizeString("aab"));     // "aba"
    }
}

