        heap.sort((a, b) => b[0] - a[0]);  // Keep max at front

        // Place the most frequent remaining char
        const curr = heap.shift();
        result += String.fromCharCode(curr[1] + 97);
        curr[0]--;

        // Push previous char back — it is now safe to use again
        if (prev && prev[0] > 0) heap.push(prev);
        prev = curr;  // Hold: cannot place this char next step
    }

    return result;
}

