import java.util.PriorityQueue;
import java.util.Collections;

public class IPO {

    public static int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int n = profits.length;

        // Min-heap: locked projects sorted by capital needed (cheapest first)
        PriorityQueue<int[]> minCapital = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        // Max-heap: unlocked projects sorted by profit (most profitable first)
        PriorityQueue<Integer> maxProfit = new PriorityQueue<>(Collections.reverseOrder());

        for (int i = 0; i < n; i++) {
            minCapital.offer(new int[]{capital[i], profits[i]});
        }

        for (int i = 0; i < k; i++) {
            // Unlock all projects we can now afford
            while (!minCapital.isEmpty() && minCapital.peek()[0] <= w) {
                maxProfit.offer(minCapital.poll()[1]);
            }

            // No affordable projects left
            if (maxProfit.isEmpty()) break;

            // Pick the most profitable one
            w += maxProfit.poll();
        }

        return w;
    }

    public static void main(String[] args) {
        // k=4, W=0
        // Projects: A(cap=0,profit=2), B(cap=0,profit=1), C(cap=2,profit=3)
        //           D(cap=3,profit=5), E(cap=5,profit=8)
        int[] profits = {2, 1, 3, 5, 8};
        int[] capital = {0, 0, 2, 3, 5};
        System.out.println(findMaximizedCapital(4, 0, profits, capital));  // 18
        // Round 1: unlock A,B. Pick A(2). W=2
        // Round 2: unlock C.   Pick C(3). W=5
        // Round 3: unlock D,E. Pick E(8). W=13
        // Round 4: no unlock.  Pick D(5). W=18
    }
}

