import java.util.*;

// Approach: Two TreeMaps (balanced BST) — O(n log k), handles duplicates
// small: max-ordered (lower half), large: min-ordered (upper half)
// small.size() == large.size() (even k) or small.size() == large.size() + 1 (odd k)
public class SlidingWindowMedian {

    public static double[] medianSlidingWindow(int[] nums, int k) {
        // TreeMap<value, count> — tracks duplicates without separate lazy-delete map
        TreeMap<Integer, Integer> small = new TreeMap<>(Collections.reverseOrder());
        TreeMap<Integer, Integer> large = new TreeMap<>();
        int smallSize = 0, largeSize = 0;
        double[] result = new double[nums.length - k + 1];

        for (int i = 0; i < nums.length; i++) {
            // Insert into correct half
            if (smallSize == 0 || nums[i] <= small.firstKey()) {
                small.merge(nums[i], 1, Integer::sum);
                smallSize++;
            } else {
                large.merge(nums[i], 1, Integer::sum);
                largeSize++;
            }

            // Rebalance so small has equal or one more element
            while (smallSize > largeSize + 1) { move(small, large); smallSize--; largeSize++; }
            while (largeSize > smallSize)     { move(large, small); largeSize--; smallSize++; }

            if (i >= k - 1) {
                // Compute median
                result[i - k + 1] = k % 2 == 1
                    ? small.firstKey()
                    : ((double) small.firstKey() + large.firstKey()) / 2;

                // Remove element leaving the window
                int out = nums[i - k + 1];
                if (out <= small.firstKey()) { remove(small, out); smallSize--; }
                else                         { remove(large, out); largeSize--; }
            }
        }
        return result;
    }

    private static void move(TreeMap<Integer, Integer> from, TreeMap<Integer, Integer> to) {
        int v = from.firstKey();
        to.merge(v, 1, Integer::sum);
        remove(from, v);
    }

    private static void remove(TreeMap<Integer, Integer> map, int v) {
        if (map.get(v) == 1) map.remove(v);
        else map.merge(v, -1, Integer::sum);
    }

    public static void main(String[] args) {
        int[] nums = {1, 3, -1, -3, 5, 3, 6, 7};
        int k = 3;
        System.out.println(Arrays.toString(medianSlidingWindow(nums, k)));
        // [1.0, -1.0, -1.0, 3.0, 5.0, 6.0]
    }
}

