// Sliding Window Median using sorted array (simpler for interviews)
function medianSlidingWindow(nums, k) {
    const window = [];  // Sorted window
    const result = [];

    for (let i = 0; i < nums.length; i++) {
        // Insert maintaining sorted order using binary search
        const insertIdx = binarySearchInsert(window, nums[i]);
        window.splice(insertIdx, 0, nums[i]);

        // Remove element leaving the window
        if (i >= k) {
            const removeIdx = binarySearchFind(window, nums[i - k]);
            window.splice(removeIdx, 1);
        }

        // Record median when window is full
        if (i >= k - 1) {
            const mid = Math.floor(k / 2);
            if (k % 2 === 1) {
                result.push(window[mid]);
            } else {
                result.push((window[mid - 1] + window[mid]) / 2);
            }
        }
    }
    return result;
}

// Find insertion point for sorted array
function binarySearchInsert(arr, target) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

// Find exact position of element
function binarySearchFind(arr, target) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

// Example usage
const nums = [1, 3, -1, -3, 5, 3, 6, 7];
const k = 3;

console.log("Medians:", medianSlidingWindow(nums, k));
// Output: [1, -1, -1, 3, 5, 6]

tutorial.content:
## Mistake 1: Wrong Heap Type for Top K

The most common interview mistake.

```
WRONG: "I want K largest, so I'll use max-heap"
RIGHT: "I want K largest, so I'll use MIN-heap of size K"
```

| Goal | Heap type | Root contains |
|------|-----------|---------------|
| K largest | Min-heap of size K | Kth largest (weakest keeper) |
| K smallest | Max-heap of size K | Kth smallest (weakest keeper) |

Use the **opposite** heap so the root is always the element most likely to be kicked out when a better candidate arrives.

## Mistake 2: Forgetting to Cap Heap Size

```java
// WRONG: heap grows to N elements
for (int num : nums) {
    heap.offer(num);
}

// RIGHT: evict immediately when size exceeds K
for (int num : nums) {
    heap.offer(num);
    if (heap.size() > k) {
        heap.poll();
    }
}
```

Debug check: after the loop, `heap.size()` should equal `min(k, n)`.

## Mistake 3: Operating on an Empty Heap

```java
// WRONG: throws NoSuchElementException when heap is empty
return heap.peek();
return heap.poll();

// RIGHT: always guard first
if (heap.isEmpty()) return -1;
return heap.peek();
```

This is especially common in two-heap problems where one half may be empty at the start.

## Mistake 4: Java Comparator Overflow

Subtracting integers in a comparator causes **silent overflow** for large values.

```java
// WRONG: overflows when values are far apart (e.g. MAX_INT and negative)
PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);

// RIGHT: use Integer.compare — no overflow
PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
```

Why it overflows: `0 - Integer.MIN_VALUE` = `Integer.MIN_VALUE` in 32-bit arithmetic (wraps to negative), flipping the comparison result and silently corrupting sort order.

Quick reference:
```java
// Min-heap of integers (default)
new PriorityQueue<>()

// Max-heap of integers
new PriorityQueue<>(Collections.reverseOrder())
new PriorityQueue<>((a, b) -> b - a)   // OK only when values fit in int difference

// Custom objects — always use Integer.compare
new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));  // min by first field
new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));  // max by first field
```

## Mistake 5: Two Heaps Imbalance (Streaming Median)

After every insert or remove, the two halves must satisfy:

```
|small.size() - large.size()| <= 1
```

If you forget to rebalance, the median calculation will be wrong even though the values are all present.

```java
// WRONG: insert then immediately read median without rebalancing
small.offer(num);
return findMedian();  // small might now have 2 more than large!

// RIGHT: always rebalance after insert
small.offer(num);
if (small.size() > large.size() + 1) {
    large.offer(small.poll());
}
if (large.size() > small.size()) {
    small.offer(large.poll());
}
return findMedian();
```

## Mistake 6: Off-by-One in Meeting Rooms (>= vs >)

When checking if a room can be reused, use `>=` not `>`.

```java
// WRONG: misses the case where a meeting ends exactly when the next one starts
if (intervals[i][0] > endTimes.peek()) {
    endTimes.poll();  // reuse room
}

// RIGHT: a room ending at time 10 IS free for a meeting starting at 10
if (intervals[i][0] >= endTimes.peek()) {
    endTimes.poll();  // reuse room
}
```

Example: `[5, 10]` ends at 10. `[10, 15]` starts at 10. The room is free — only `>=` catches this.

## Mistake 7: Reorganize String — Wrong Operation Order

In the "hold previous" technique, pop first, then push prev back.

```java
// WRONG: push prev before popping — can pick the same char again
if (prev != null && prev[0] > 0) heap.offer(prev);  // put prev back first
int[] curr = heap.poll();                             // then pop — might get prev!

// RIGHT: pop first, place it, then push prev back
int[] curr = heap.poll();       // pick most frequent (prev is still held out)
sb.append((char)(curr[1] + 'a'));
curr[0]--;
if (prev != null && prev[0] > 0) heap.offer(prev);  // now safe to return prev
prev = curr;
```

The point of "holding" is to keep the previous character OUT of the heap for one step. Pushing it back before popping defeats the purpose.

## Mistake 8: JavaScript Array is Not a Heap

```javascript
// This is O(n log n) per operation — not O(log n)
const heap = [];
heap.push(5);
heap.sort((a, b) => a - b);   // O(n log n) each time!
heap.shift();                  // O(n) — shifts entire array

// In interviews, be explicit:
// "I'm using a sorted array to show the logic clearly.
//  In production I'd use a proper heap (e.g. @datastructures-js/priority-queue)."
```

## Debugging Checklist

| Symptom | Likely cause | Check |
|---------|-------------|-------|
| Wrong K elements returned | Wrong heap type (min vs max) | Should root be the weakest or strongest keeper? |
| Heap too large / memory exceeded | Not capping at size K | `heap.size() > k` after each insert? |
| Crash on `peek()` or `poll()` | Empty heap access | Guard with `isEmpty()` before every access |
| Wrong sort order with large values | Comparator overflow | Use `Integer.compare` not subtraction |
| Median wrong despite correct values | Two heaps out of balance | `|small.size - large.size| <= 1` after each op? |
| Meeting rooms count too high | Using `>` instead of `>=` | Boundary: end==start means room IS free |
| Adjacent same chars in output | Wrong order in reorganize-string hold | Pop first, then push prev back |
| TLE in JavaScript | `sort()` inside loop | O(n^2 log n) total — acknowledge in interview |

## Edge Cases to Always Test

```
1. k = 1          — single element result
2. k = n          — all elements in heap
3. k > n          — return all elements
4. empty input    — return [] or 0
5. all equal      — duplicates handled correctly
6. negatives      — comparator works with negative numbers
7. MAX_INT values — no overflow in comparator
8. window = 1     — sliding window: every element is its own median
```

## Interview Communication Tips

### Before You Code

Ask these questions first: they change the entire approach:

```
"K largest elements, or just the Kth largest? (all K vs one value)"
"Is data streaming in, or is the whole array available upfront?"
"Do I need to handle duplicates?"
"What if K is larger than the array size?"
"Is the input already sorted? Can I modify it in place?"
"For meeting rooms: does a meeting ending at T free the room for one starting at T?"
"For window median: what precision is needed for even-sized windows?"
```

### Stating Your Approach

Be explicit about which heap you pick and why:

```
Top K:
  "I will use a MIN-heap of size K. As I scan the array, I evict
   the root whenever the heap exceeds K. At the end the root is
   the Kth largest, the weakest element I am keeping."

Streaming Median:
  "I will use two heaps: a max-heap for the lower half and a
   min-heap for the upper half. After every insert I rebalance
   so the sizes differ by at most one. The median is always
   at one of the two roots."

Meeting Rooms:
  "I sort by start time. A min-heap of end times tells me whether
   the earliest-ending room is free. If the new meeting starts at
   or after that end time, I reuse the room; otherwise I add one."

IPO:
  "I use two heaps. A min-heap by capital keeps locked projects.
   Each round I move everything I can afford into a max-heap by
   profit, then greedily pick the best."
```

### Drawing Heap State

Always draw the heap when you explain or debug:

```
Min-heap storing end times [10, 30, 20]:

         10          <- root (earliest ending, check this first)
        /  \
       30   20

Array form: [10, 30, 20]
```

### Handling the JavaScript Heap Gap

JavaScript has no built-in heap. Say this once, clearly:

```
"JavaScript does not have a built-in priority queue. For this
 interview I will simulate one with a sorted array to keep the
 logic readable. The real time complexity would be O(n log k)
 with a proper heap; the sorted array gives O(n k), but the
 logic is identical."
```

---

## Java Templates

### Template 1: Top K Elements

```java
// K largest: min-heap of size K. Root = Kth largest (weakest keeper).
// K smallest: max-heap of size K. Root = Kth smallest (weakest keeper).
PriorityQueue<Integer> heap = new PriorityQueue<>();  // min-heap for K largest

for (int num : nums) {
    heap.offer(num);
    if (heap.size() > k) {
        heap.poll();  // evict the smallest (it is no longer in top K)
    }
}
// heap contains the K largest. heap.peek() = Kth largest.
```

### Template 2: Two Heaps (Streaming Median)

```java
PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder()); // max-heap, lower half
PriorityQueue<Integer> large = new PriorityQueue<>();  // min-heap, upper half

void addNum(int num) {
    // Always insert into small first, then push the max of small to large.
    // This keeps small <= large at all times.
    small.offer(num);
    large.offer(small.poll());

    // Rebalance: small should have equal or one more element than large.
    if (large.size() > small.size()) {
        small.offer(large.poll());
    }
}

double findMedian() {
    return small.size() > large.size()
        ? small.peek()                                    // odd total: middle is in small
        : (small.peek() + large.peek()) / 2.0;           // even total: average the two middles
}
```

### Template 3: Merge K Sorted Sequences

```java
// heap stores [value, arrayIndex, elementIndex]
PriorityQueue<int[]> heap = new PriorityQueue<>(
    (a, b) -> Integer.compare(a[0], b[0])  // min by value
);

for (int i = 0; i < arrays.length; i++) {
    if (arrays[i].length > 0) {
        heap.offer(new int[]{arrays[i][0], i, 0});
    }
}

List<Integer> result = new ArrayList<>();
while (!heap.isEmpty()) {
    int[] curr = heap.poll();
    result.add(curr[0]);
    int nextIdx = curr[2] + 1;
    if (nextIdx < arrays[curr[1]].length) {
        heap.offer(new int[]{arrays[curr[1]][nextIdx], curr[1], nextIdx});
    }
}
```

### Template 4: Meeting Rooms II (Min-Heap of End Times)

```java
Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));  // sort by start
PriorityQueue<Integer> endTimes = new PriorityQueue<>();         // min-heap of end times

for (int[] interval : intervals) {
    // If the earliest-ending room is free, reuse it
    if (!endTimes.isEmpty() && endTimes.peek() <= interval[0]) {
        endTimes.poll();
    }
    endTimes.offer(interval[1]);  // assign this meeting a room
}
return endTimes.size();  // peak concurrent meetings
```

### Template 5: Scheduling / Reorganize (Max-Heap by Frequency)

```java
// Count frequencies, build max-heap
int[] freq = new int[26];
for (char c : s.toCharArray()) freq[c - 'a']++;

PriorityQueue<int[]> heap = new PriorityQueue<>(
    (a, b) -> Integer.compare(b[0], a[0])  // max by frequency
);
for (int i = 0; i < 26; i++) {
    if (freq[i] > 0) heap.offer(new int[]{freq[i], i});
}

StringBuilder sb = new StringBuilder();
int[] prev = null;

while (!heap.isEmpty()) {
    int[] curr = heap.poll();           // most frequent available char
    sb.append((char)(curr[1] + 'a'));
    curr[0]--;
    if (prev != null && prev[0] > 0) { // previous char is now safe to reuse
        heap.offer(prev);
    }
    prev = curr;                        // hold curr out for one step
}
return sb.toString();
```

### Template 6: IPO: Two Heaps (Lock + Pick)

```java
// Min-heap by capital: locked projects, sorted by cost
PriorityQueue<int[]> locked = new PriorityQueue<>(
    (a, b) -> Integer.compare(a[0], b[0])
);
// Max-heap by profit: unlocked projects, pick the best
PriorityQueue<Integer> available = new PriorityQueue<>(Collections.reverseOrder());

for (int i = 0; i < n; i++) {
    locked.offer(new int[]{capital[i], profits[i]});
}

for (int round = 0; round < k; round++) {
    // Unlock everything we can now afford
    while (!locked.isEmpty() && locked.peek()[0] <= w) {
        available.offer(locked.poll()[1]);
    }
    if (available.isEmpty()) break;   // nothing affordable, stop early
    w += available.poll();            // take the most profitable
}
return w;
