### Template 3: Sliding Window Median (Sorted Array)

```javascript
function medianSlidingWindow(nums, k) {
    const sorted = [], result = [];

    function insertIdx(arr, val) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const m = (lo + hi) >> 1;
            if (arr[m] < val) lo = m + 1; else hi = m;
        }
        return lo;
    }

    for (let i = 0; i < nums.length; i++) {
        sorted.splice(insertIdx(sorted, nums[i]), 0, nums[i]);
        if (i >= k) sorted.splice(insertIdx(sorted, nums[i - k]), 1);
        if (i >= k - 1) {
            const mid = k >> 1;
            result.push(k % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2);
        }
    }
    return result;
}
