public int minMeetingRooms(int[][] intervals) {
    // Create events: +1 for start, -1 for end
    List<int[]> events = new ArrayList<>();

    for (int[] meeting : intervals) {
        events.add(new int[]{meeting[0], 1});   // start
        events.add(new int[]{meeting[1], -1});  // end
    }

    // Sort by time. If same time, end (-1) before start (+1)
    // Use Integer.compare to avoid overflow
    events.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));

    int rooms = 0, maxRooms = 0;
    for (int[] event : events) {
        rooms += event[1];  // +1 or -1
        maxRooms = Math.max(maxRooms, rooms);
    }

    return maxRooms;
}

// Meeting Rooms I: Can attend all meetings?
public boolean canAttendMeetings(int[][] intervals) {
    // Sort by start time (use Integer.compare to avoid overflow)
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

    // Check if any meeting starts before previous ends
    for (int i = 1; i < intervals.length; i++) {
        if (intervals[i][0] < intervals[i-1][1]) {
            return false;  // Conflict!
        }
    }
    return true;  // No conflicts
}

