    int lastEnd = intervals[0][1];

    for (int i = 1; i < intervals.length; i++) {
        if (intervals[i][0] < lastEnd) {
            // Overlap! Remove one, keep the one that ends earlier
            removals++;
            lastEnd = Math.min(lastEnd, intervals[i][1]);
        } else {
            // No overlap
            lastEnd = intervals[i][1];
        }
    }

    return removals;
}

