public int[][] intervalIntersection(int[][] A, int[][] B) {
    List<int[]> result = new ArrayList<>();
    int i = 0, j = 0;

    while (i < A.length && j < B.length) {
        // Find the overlap
        int start = Math.max(A[i][0], B[j][0]);  // Later start
        int end = Math.min(A[i][1], B[j][1]);    // Earlier end

        // If valid intersection (start <= end)
        if (start <= end) {
            result.add(new int[]{start, end});
        }

        // Move pointer with smaller end (that interval is "done")
        if (A[i][1] < B[j][1]) {
            i++;
        } else {
            j++;
        }
    }

    return result.toArray(new int[0][]);
}

