public int findMinArrowShots(int[][] points) {
    if (points.length == 0) return 0;

    // Sort by end point
    // Use Integer.compare to avoid overflow!
    Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));

    int arrows = 1;
    int arrowPos = points[0][1];  // Shoot at first balloon's end

    for (int i = 1; i < points.length; i++) {
        // If balloon starts AFTER arrow position, need new arrow
        // Note: > not >= (touching counts as overlap here)
        if (points[i][0] > arrowPos) {
            arrows++;
            arrowPos = points[i][1];
        }
        // Otherwise, current arrow already pops this balloon
    }

    return arrows;
}

