public List<Interval> employeeFreeTime(List<List<Interval>> schedule) {
    // Step 1: Flatten all intervals into one list
    List<Interval> all = new ArrayList<>();
    for (List<Interval> employee : schedule) {
        all.addAll(employee);
    }

    // Step 2: Sort by start time (use Integer.compare to avoid overflow)
    Collections.sort(all, (a, b) -> Integer.compare(a.start, b.start));

    // Step 3: Merge overlapping work intervals
    List<Interval> merged = new ArrayList<>();
    merged.add(all.get(0));

    for (int i = 1; i < all.size(); i++) {
        Interval last = merged.get(merged.size() - 1);
        Interval curr = all.get(i);

        if (curr.start <= last.end) {
            // Overlaps - extend
            last.end = Math.max(last.end, curr.end);
        } else {
            // No overlap - add new work block
            merged.add(curr);
        }
    }

    // Step 4: Gaps between work blocks = free time
    List<Interval> freeTime = new ArrayList<>();
    for (int i = 1; i < merged.size(); i++) {
        int freeStart = merged.get(i - 1).end;
        int freeEnd = merged.get(i).start;
        freeTime.add(new Interval(freeStart, freeEnd));
    }

    return freeTime;
}

