code.java:
/*
 * Approach: Sort and Sweep with Min-Heap
 * 
 * Idea:
 * - Process queries from smallest to largest value
 * - As we move right, intervals "enter" when query >= their start
 * - Intervals "exit" when query > their end (they can't contain the query anymore)
 * - Use a min-heap to always get the shortest valid interval
 * 
 * Why this works:
 * - Sorting queries means we never go backwards
 * - Each interval is added once and removed once
 * - Heap gives us the smallest length in O(log n)
 */
public int[] minInterval(int[][] intervals, int[] queries) {
    int n = intervals.length;
    int m = queries.length;
    int[] answer = new int[m];
    Arrays.fill(answer, -1);

    // Sort intervals by start time
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

    // Store each query with its original index
    // We need this because we process queries in sorted order
    // but must return answers in original order
    int[][] sortedQueries = new int[m][2];
    for (int j = 0; j < m; j++) {
        sortedQueries[j][0] = queries[j];  // query value
        sortedQueries[j][1] = j;           // original index
    }

    // Process queries from smallest to largest
    Arrays.sort(sortedQueries, (a, b) -> Integer.compare(a[0], b[0]));

    // Min-Heap stores [intervalLength, intervalEnd]
    // Smallest length stays on top
    PriorityQueue<int[]> minHeap = new PriorityQueue<>(
        (a, b) -> Integer.compare(a[0], b[0])
    );

    int intervalIndex = 0;

    for (int[] query : sortedQueries) {
        int queryValue = query[0];
        int originalIndex = query[1];

        // Add every interval whose start <= current query
        // These intervals MIGHT contain the query point
        while (intervalIndex < n && intervals[intervalIndex][0] <= queryValue) {
            int start = intervals[intervalIndex][0];
            int end = intervals[intervalIndex][1];
            int length = end - start + 1;

            minHeap.offer(new int[]{length, end});
            intervalIndex++;
        }

        // Remove intervals that cannot contain this query
        // If end < queryValue, the interval is too far left
        while (!minHeap.isEmpty() && minHeap.peek()[1] < queryValue) {
            minHeap.poll();
        }

        // The smallest valid interval is now at the top
        if (!minHeap.isEmpty()) {
            answer[originalIndex] = minHeap.peek()[0];
        }
    }

    return answer;
}

code.javascript:
/*
 * Approach: Sort and Sweep with Min-Heap
 * 
 * Idea:
 * - Process queries from smallest to largest value
 * - As we move right, intervals "enter" when query >= their start
 * - Intervals "exit" when query > their end (they can't contain the query anymore)
 * - Use a min-heap to always get the shortest valid interval
 * 
 * Why this works:
 * - Sorting queries means we never go backwards
 * - Each interval is added once and removed once
 * - Heap gives us the smallest length in O(log n)
 */
function minInterval(intervals, queries) {
    const n = intervals.length;
    const m = queries.length;
    const answer = new Array(m).fill(-1);

    // Sort intervals by start time
    intervals.sort((a, b) => a[0] - b[0]);

    // Store each query with its original index
    // We need this because we process queries in sorted order
    // but must return answers in original order
    const sortedQueries = queries
        .map((val, idx) => [val, idx])
        .sort((a, b) => a[0] - b[0]);

    // Min-Heap stores [intervalLength, intervalEnd]
    // We use an array and keep it sorted (simple heap simulation)
    const minHeap = [];

    let intervalIndex = 0;

    for (const [queryValue, originalIndex] of sortedQueries) {
        // Add every interval whose start <= current query
        // These intervals MIGHT contain the query point
        while (intervalIndex < n && intervals[intervalIndex][0] <= queryValue) {
            const [start, end] = intervals[intervalIndex];
            const length = end - start + 1;

            minHeap.push([length, end]);
            intervalIndex++;
        }

        // Sort by length (smallest first) to simulate min-heap
        minHeap.sort((a, b) => a[0] - b[0]);

        // Remove intervals that cannot contain this query
        // If end < queryValue, the interval is too far left
        while (minHeap.length > 0 && minHeap[0][1] < queryValue) {
            minHeap.shift();
        }

        // The smallest valid interval is now at the front
        if (minHeap.length > 0) {
            answer[originalIndex] = minHeap[0][0];
        }
    }

    return answer;
}

