    let sum = 0, count = 0;

    for (let num of nums) {
        sum += num;
        // If (sum - k) was seen before, those positions
        // mark starts of valid subarrays ending here
        count += prefixCount.get(sum - k) || 0;
        prefixCount.set(sum, (prefixCount.get(sum) || 0) + 1);
    }
    return count;
