for (int i = 0; i < n; i++) {
    sum += nums[i];
    if (firstIndex.containsKey(sum - k)) {
        maxLen = Math.max(maxLen, i - firstIndex.get(sum - k));
    }
    firstIndex.putIfAbsent(sum, i);  // Only first occurrence
}
