function minWindow(s, t) {
    const tFreq = new Map(), sFreq = new Map();
    for (const c of t) tFreq.set(c, (tFreq.get(c) || 0) + 1);

    let matches = 0, required = tFreq.size;
    let left = 0, minLen = Infinity, result = '';

    for (let right = 0; right < s.length; right++) {
        const c = s[right];
        sFreq.set(c, (sFreq.get(c) || 0) + 1);
        if (sFreq.get(c) === tFreq.get(c)) matches++;

        while (matches === required) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                result = s.slice(left, right + 1);
            }
            const leftChar = s[left];
            if (sFreq.get(leftChar) === tFreq.get(leftChar)) matches--;
            sFreq.set(leftChar, sFreq.get(leftChar) - 1);
            left++;
        }
    }
    return result;
}

