function checkInclusion(s1, s2) {
    if (s1.length > s2.length) return false;

    const s1Freq = new Array(26).fill(0);
    const s2Freq = new Array(26).fill(0);

    // Build s1 frequency
    for (const c of s1) {
        s1Freq[c.charCodeAt(0) - 97]++;
    }

    for (let i = 0; i < s2.length; i++) {
        // Add right char
        s2Freq[s2.charCodeAt(i) - 97]++;

        // Remove left char when window exceeds s1 length
        if (i >= s1.length) {
            s2Freq[s2.charCodeAt(i - s1.length) - 97]--;
        }

        // Compare frequencies
        if (i >= s1.length - 1) {
            if (arraysEqual(s1Freq, s2Freq)) return true;
        }
    }

    return false;
}

